<script setup lang="ts">
import{ref}from'vue';import{useRouter}from'vue-router';import{apiRequest}from'@/api/client';import{trustedFocusParcel}from'@/features/aiActions';import type{AiQueryResponse,AiQueryResult}from'@/types/api'
const router=useRouter(),question=ref(''),loading=ref(false),error=ref(''),history=ref<Array<{question:string;response:AiQueryResponse}>>([])
const shortcuts=['分析今日运营','查找滞留件','今天有哪些异常件没处理','哪个货架现在最满']
async function ask(value=question.value){if(!value.trim())return;loading.value=true;error.value='';try{const response=await apiRequest<AiQueryResponse>('/api/ai/query',{method:'POST',body:JSON.stringify({question:value})});history.value.unshift({question:value,response});question.value='';const focus=trustedFocusParcel(response);if(focus)await router.push(`/digital-twin?parcelId=${focus}`)}catch(e){error.value=e instanceof Error?e.message:'AI 助手暂时不可用'}finally{loading.value=false}}
function locate(item:AiQueryResult,path:string){if(item.parcelId)router.push(`${path}?parcelId=${item.parcelId}`)}
</script>
<template><section class="page"><header class="page-heading"><div><p class="eyebrow">MAIMAIYA · SAFE INTENT GATEWAY</p><h1>AI 助手</h1><p>自然语言仅解析为 Java 白名单只读查询，不执行模型生成的 SQL 或命令</p></div></header><div class="button-row"><button v-for="item in shortcuts" :key="item" class="ghost" @click="ask(item)">{{item}}</button></div><form class="action-card" @submit.prevent="ask()"><textarea v-model="question" required placeholder="例如：找出超过7天没取的顺丰快递"></textarea><button class="primary" :disabled="loading">{{loading?'查询中…':'发送'}}</button></form><p v-if="error" class="error" role="alert">{{error}}</p><div v-if="!history.length&&!loading" class="state-panel">输入问题开始安全查询</div><article v-for="entry in history" :key="entry.question+entry.response.answer" class="action-card"><p class="eyebrow">QUERY</p><h3>{{entry.question}}</h3><p>{{entry.response.answer}}</p><div v-if="entry.response.results.length" class="data-table-wrap"><table><thead><tr><th>结果</th><th>位置</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in entry.response.results" :key="`${item.parcelId}-${item.trackingNo}`"><td>{{item.trackingNo}}</td><td>{{item.shelfCode??'—'}} / {{item.slotCode??'—'}}</td><td>{{item.status}}</td><td><div v-if="item.parcelId" class="button-row"><button class="ghost" @click="locate(item,'/parcels')">查看详情</button><button class="ghost" @click="locate(item,'/warehouse')">2D 定位</button><button class="primary compact" @click="locate(item,'/digital-twin')">3D 定位</button></div></td></tr></tbody></table></div><p v-if="entry.response.results.length>1" class="muted">找到多条结果，请人工选择，不会自动定位第一条。</p></article></section></template>
